import { PrismaClient } from "@prisma/client";
import { Client } from "ssh2";
import { decryptSecret } from "../lib/crypto-box";

const SERVER_ID = "cmsc9l72y000ghl7iyd87u5ja";
const EXPECTED_IP = "51.79.226.200";

const SMTP_HOST = "mail.nxeon.cloud";
const SMTP_PORT = "587";
const SMTP_USERNAME = "noreply@soulpilates.com.vn";
const SMTP_PASSWORD = "WQNjgPBCRwfDcOTaCANP8A9E";

const prisma = new PrismaClient();

type ExecResult = { code: number | null; stdout: string; stderr: string };

function connect(host: string, password: string): Promise<Client> {
  return new Promise((resolve, reject) => {
    const conn = new Client();
    conn
      .on("ready", () => resolve(conn))
      .on("error", reject)
      .connect({ host, port: 22, username: "root", password, readyTimeout: 30000 });
  });
}

function exec(conn: Client, cmd: string): Promise<ExecResult> {
  return new Promise((resolve, reject) => {
    conn.exec(cmd, (err, stream) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      let code: number | null = null;
      stream
        .on("close", (c: number) => resolve({ code: c ?? code, stdout, stderr }))
        .on("exit", (c: number) => (code = c))
        .on("data", (d: Buffer) => (stdout += d.toString()))
        .stderr.on("data", (d: Buffer) => (stderr += d.toString()));
    });
  });
}

async function main() {
  const report: Record<string, unknown> = {};

  const server = await prisma.server.findUnique({
    where: { id: SERVER_ID },
    select: { ipAddress: true, rootPasswordEnc: true },
  });
  if (!server) throw new Error(`Server ${SERVER_ID} not found`);
  const ip = server.ipAddress;
  report.ipAddress = ip;

  // STEP 1: assert IP
  if (ip !== EXPECTED_IP) {
    console.log(JSON.stringify({ ABORT: `IP mismatch: got ${ip}, expected ${EXPECTED_IP}`, report }, null, 2));
    return;
  }
  console.log(`IP assertion OK: ${ip} === ${EXPECTED_IP}`);

  const password = decryptSecret(server.rootPasswordEnc);
  if (!password) throw new Error("Failed to decrypt rootPasswordEnc");

  const conn = await connect(ip, password);
  console.log("SSH connected to", ip);

  try {
    // STEP 2: python smtplib test send from .200
    const py = `import smtplib, ssl
from email.mime.text import MIMEText
from email.utils import formatdate, make_msgid
HOST="${SMTP_HOST}"; PORT=${SMTP_PORT}
USER="${SMTP_USERNAME}"; PW="${SMTP_PASSWORD}"
FROM="Soul Pilates Da Nang <noreply@soulpilates.com.vn>"
TO="haxkodi@gmail.com"
html="""<html><body>
<h2>Soul Pilates &#8594; Nxeon Mail relay is live</h2>
<p>This message confirms the Soul Pilates app can now relay outbound email through the Nxeon Mail platform (mail.nxeon.cloud:587, STARTTLS), authenticating as noreply@soulpilates.com.vn.</p>
</body></html>"""
msg=MIMEText(html,"html","utf-8")
msg["Subject"]="Soul Pilates → Nxeon Mail relay is live"
msg["From"]=FROM; msg["To"]=TO
msg["Date"]=formatdate(localtime=True); msg["Message-ID"]=make_msgid(domain="soulpilates.com.vn")
ctx=ssl.create_default_context()
s=smtplib.SMTP(HOST,PORT,timeout=30)
s.ehlo()
s.starttls(context=ctx)
s.ehlo()
s.login(USER,PW)
s.sendmail("noreply@soulpilates.com.vn",[TO],msg.as_string())
s.quit()
print("SEND_OK")
`;
    const pyB64 = Buffer.from(py, "utf8").toString("base64");
    const sendCmd =
      `f=/tmp/_sp_smtptest.py; echo ${pyB64} | base64 -d > $f && python3 $f; rc=$?; rm -f $f; exit $rc`;
    const sendRes = await exec(conn, sendCmd);
    console.log("--- smtp test stdout ---\n" + sendRes.stdout);
    if (sendRes.stderr.trim()) console.log("--- smtp test stderr ---\n" + sendRes.stderr);
    console.log("--- smtp test exit:", sendRes.code, "---");

    const sendOk = sendRes.stdout.includes("SEND_OK");
    report.sendOk = sendOk;

    // STEP 3: stop if not SEND_OK
    if (!sendOk) {
      report.smtpError = (sendRes.stderr || sendRes.stdout || "unknown error").trim();
      console.log("STOP: test send did not print SEND_OK. No config changed.");
      console.log(JSON.stringify({ report }, null, 2));
      return;
    }
    console.log("SEND_OK received.");

    // STEP 4: backup + edit prod.env, recreate backend
    const editorPy = `import re
p="/opt/soulpilates/prod.env"
vals={"SMTP_HOST":"${SMTP_HOST}","SMTP_PORT":"${SMTP_PORT}","SMTP_USERNAME":"${SMTP_USERNAME}","SMTP_PASSWORD":"${SMTP_PASSWORD}"}
lines=open(p,encoding="utf-8").read().splitlines()
seen=set()
out=[]
for ln in lines:
    m=re.match(r"^(\\s*)([A-Za-z0-9_]+)(\\s*)=(.*)$", ln)
    if m and m.group(2) in vals:
        k=m.group(2); out.append("%s=%s"%(k,vals[k])); seen.add(k)
    else:
        out.append(ln)
for k,v in vals.items():
    if k not in seen: out.append("%s=%s"%(k,v))
open(p,"w",encoding="utf-8").write("\\n".join(out)+"\\n")
print("ENV_UPDATED")
`;
    const editB64 = Buffer.from(editorPy, "utf8").toString("base64");
    const step4 =
      `set -e; cd /opt/soulpilates; ` +
      `cp -a prod.env prod.env.bak-200mail; ` +
      `f=/tmp/_sp_envedit.py; echo ${editB64} | base64 -d > $f && python3 $f; rm -f $f; ` +
      `echo '--- resulting SMTP_ lines ---'; grep -E '^SMTP_' prod.env | sed 's/^SMTP_PASSWORD=.*/SMTP_PASSWORD=***REDACTED***/'; ` +
      `echo '--- recreating backend ---'; ` +
      `docker compose -f docker-compose.prod.yml -p soulpilates --env-file prod.env up -d --force-recreate --no-deps backend`;
    const s4 = await exec(conn, step4);
    console.log("--- step4 stdout ---\n" + s4.stdout);
    if (s4.stderr.trim()) console.log("--- step4 stderr ---\n" + s4.stderr);
    console.log("--- step4 exit:", s4.code, "---");
    report.step4Exit = s4.code;

    // give backend a moment
    await exec(conn, "sleep 5");

    // STEP 5: health checks
    const health = await exec(
      conn,
      `echo BACKEND_PS=; docker ps --filter name=soulpilates-prod-backend --format '{{.Names}} {{.Status}}'; ` +
        `echo FRONTEND_CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3719/); ` +
        `echo PUBLIC_CODE=$(curl -s -o /dev/null -w '%{http_code}' -H 'Host: soulpilates.com.vn' https://127.0.0.1/ -k)`,
    );
    console.log("--- health stdout ---\n" + health.stdout);
    if (health.stderr.trim()) console.log("--- health stderr ---\n" + health.stderr);
    report.health = health.stdout.trim();

    console.log("\n===== FINAL REPORT =====");
    console.log(JSON.stringify({ ...report, newSmtp: { SMTP_HOST, SMTP_PORT, SMTP_USERNAME, SMTP_PASSWORD: "***REDACTED***" } }, null, 2));
  } finally {
    conn.end();
  }
}

main()
  .catch((e) => {
    console.error("FATAL:", e);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
